html:
{%- set _logo_url = frappe.db.get_default("dw_logo_url", "watch_doctor") or "" -%}
{%- set _default_company = doc.company or frappe.db.get_value("Global Defaults", None, "default_company") or "" -%}
{%- set _general_config_exists = frappe.db.exists("DocType", "DW General Configuration") -%}
{%- set _company_name = (frappe.db.get_single_value("DW General Configuration", "company_name") if _general_config_exists else "") or (frappe.db.get_value("Company", _default_company, "company_name") if _default_company else "") or _default_company or "Watch Doctor" -%}
{%- set _company_phone = (frappe.db.get_single_value("DW General Configuration", "company_phone") if _general_config_exists else "") or (frappe.db.get_value("Company", _default_company, "phone_no") if _default_company else "") or "" -%}
{%- set _company_email = (frappe.db.get_single_value("DW General Configuration", "company_email") if _general_config_exists else "") or (frappe.db.get_value("Company", _default_company, "email") if _default_company else "") or "" -%}
{%- set _company_website = (frappe.db.get_single_value("DW General Configuration", "company_website") if _general_config_exists else "") or (frappe.db.get_value("Company", _default_company, "website") if _default_company else "") or "" -%}
{%- set _company_address = (frappe.db.get_single_value("DW General Configuration", "company_address") if _general_config_exists else "") or "" -%}
{%- set _cr_number = (frappe.db.get_single_value("DW General Configuration", "cr_number") if _general_config_exists else "") or "" -%}
{%- set _vat_registration_number = (frappe.db.get_single_value("DW General Configuration", "vat_registration_number") if _general_config_exists else "") or (frappe.db.get_value("Company", _default_company, "tax_id") if _default_company else "") or "" -%}
<style>
    @import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=DM+Sans:wght@300;400;500&display=swap');

    @page {
      size: A4;
      margin: 18mm 16mm;
      @bottom-right {
        content: "Page " counter(page) " of " counter(pages);
        font-size: 8pt;
        color: #aaa;
      }
    }

    *, *::before, *::after { box-sizing: border-box; }

    body {
      font-family: 'DM Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif;
      font-size: 9.5pt;
      color: #1a1a1a;
      line-height: 1.55;
      margin: 0;
      padding: 0;
      background: #fff;
    }

    /* ── HEADER ── */
    .doc-header {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
      align-items: center;
      column-gap: 24px;
      border-bottom: 2px solid #1a1a1a;
      padding-bottom: 18px;
      margin-bottom: 18px;
    }
    .company-info {
      display: flex;
      flex-direction: column;
      gap: 2px;
      font-size: 9pt;
      min-width: 0;
    }
    .doc-logo {
      display: flex;
      justify-content: center;
      align-items: center;
    }
    .doc-logo img {
      max-height: 72px;
      max-width: 220px;
      width: auto;
      display: block;
    }
    .doc-title-wrap {
      display: flex;
      justify-content: flex-end;
      align-items: center;
    }
    .company-name {
      font-family: 'DM Serif Display', Georgia, serif;
      font-size: 11pt;
      color: #1a1a1a;
      font-weight: 600;
    }
    .company-crno,
    .company-location {
      font-size: 8pt;
      color: #777;
    }
    .doc-title {
      font-family: 'DM Serif Display', Georgia, serif;
      font-size: 20pt;
      color: #1a1a1a;
      text-align: right;
      letter-spacing: 0.5px;
    }
    .doc-company-meta {
      font-size: 8pt;
      color: #777;
      text-align: right;
      line-height: 1.7;
      margin-top: 4px;
    }

    /* ── META BAND ── */
    .doc-meta {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      padding: 14px 0;
      border-bottom: 0.5px solid #d0d0d0;
      margin-bottom: 22px;
    }
    .customer-label {
      font-size: 8pt;
      letter-spacing: 0.8px;
      text-transform: uppercase;
      color: #999;
      margin-bottom: 4px;
    }
    .customer-name {
      font-family: 'DM Serif Display', Georgia, serif;
      font-size: 14pt;
      color: #1a1a1a;
    }
    .customer-sub {
      font-size: 8.5pt;
      color: #777;
      margin-top: 3px;
    }
    .doc-ref-table { border-collapse: collapse; font-size: 8.5pt; }
    .doc-ref-table td { padding: 3px 0; }
    .doc-ref-table td:first-child { color: #999; padding-right: 16px; }
    .doc-ref-table td:last-child { color: #1a1a1a; font-weight: 500; text-align: right; }

    /* ── ITEMS TABLE ── */
    .items-table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 0;
      table-layout: fixed;
    }
    .items-table thead tr {
      border-bottom: 1.5px solid #1a1a1a;
    }
    .items-table th {
      font-size: 8pt;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: #666;
      padding: 7px 10px;
      font-weight: 500;
      text-align: left;
    }
    .items-table th.r, .items-table td.r { text-align: right; }
    .items-table td {
      padding: 11px 10px;
      border-bottom: 0.5px solid #ebebeb;
      vertical-align: top;
      font-size: 9pt;
    }
    .item-sr { color: #bbb; font-size: 8pt; width: 28px; }
    .item-code { font-weight: 500; color: #1a1a1a; }
    .item-desc { color: #888; font-size: 8pt; margin-top: 2px; }
    .item-uom { font-size: 7.5pt; color: #bbb; display: block; margin-top: 1px; }

    /* ── SUMMARY ── */
    .summary-wrap {
      display: flex;
      justify-content: flex-end;
      padding-top: 4px;
    }
    .summary-table {
      width: 260px;
      border-collapse: collapse;
      font-size: 9pt;
    }
    .summary-table td { padding: 5px 10px; }
    .summary-table tr td:first-child { color: #888; }
    .summary-table tr td:last-child { text-align: right; color: #1a1a1a; }
    .summary-divider { border-top: 0.5px solid #d0d0d0; }
    .summary-discount td { color: #c0392b !important; }
    .summary-grand {
      border-top: 1.5px solid #1a1a1a;
    }
    .summary-grand td {
      font-family: 'DM Serif Display', Georgia, serif;
      font-size: 12.5pt !important;
      color: #1a1a1a !important;
      padding: 9px 10px !important;
    }

    /* ── TERMS ── */
    .terms-section {
      margin-top: 28px;
      padding-top: 14px;
      border-top: 0.5px solid #d0d0d0;
      font-size: 8.5pt;
      page-break-inside: avoid;
    }
    .terms-label {
      font-size: 8pt;
      letter-spacing: 0.8px;
      text-transform: uppercase;
      color: #999;
      margin-bottom: 6px;
      font-weight: 500;
    }
    .terms-label::before {
      content: '';
      display: inline-block;
      width: 24px;
      height: 1.5px;
      background: #1a1a1a;
      vertical-align: middle;
      margin-right: 8px;
    }
    .terms-body { color: #666; line-height: 1.75; }

    /* ── SIGNATURES ── */
    .sig-section {
      display: flex;
      justify-content: space-between;
      margin-top: 50px;
      page-break-inside: avoid;
    }
    .sig-block { width: 180px; }
    .sig-line {
      border-top: 0.5px solid #999;
      padding-top: 6px;
      font-size: 8pt;
      color: #888;
    }
    .sig-right { text-align: right; margin-left: auto; }

    /* ── FOOTER ── */
    .doc-footer {
      margin-top: 26px;
      padding-top: 10px;
      border-top: 0.5px solid #e0e0e0;
      text-align: center;
      font-size: 7.5pt;
      color: #ccc;
      letter-spacing: 0.4px;
    }
  </style>


  <!-- HEADER -->
  <div class="doc-header">
    <div class="company-info">
      <div class="company-name">{{ _company_name }}</div>
      {%- if _company_address %}<div class="company-location">{{ _company_address | replace("
", ", ") }}</div>{%- endif %}
      {%- if _company_phone %}<div class="company-location">Tel: {{ _company_phone }}</div>{%- endif %}
      {%- if _company_email %}<div class="company-location">{{ _company_email }}</div>{%- endif %}
      {%- if _company_website %}<div class="company-location">{{ _company_website }}</div>{%- endif %}
      {%- if _cr_number %}<div class="company-crno">CR No: {{ _cr_number }}</div>{%- endif %}
      {%- if _vat_registration_number %}<div class="company-crno">VAT Reg No: {{ _vat_registration_number }}</div>{%- endif %}
    </div>
    <div class="doc-logo">
      {%- if _logo_url -%}
      <img src="{{ _logo_url }}" alt="{{ _company_name }}" onerror="this.style.display='none'">
      {%- endif -%}
    </div>
    <div class="doc-title-wrap">
      <div class="doc-title">Invoice</div>
    </div>
  </div>

  <!-- META BAND -->
  <div class="doc-meta">
    <div>
      <div class="customer-label">Prepared for</div>
      <div class="customer-name">{{ doc.customer_name }}</div>
      {% if doc.customer_address %}
      <div class="customer-sub">{{ doc.customer_address }}</div>
      {% endif %}
    </div>
    <div>
      <table class="doc-ref-table">
        <tr>
          <td>Invoice No.</td>
          <td>{{ doc.name }}</td>
        </tr>
        <tr>
          <td>Date</td>
          <td>{{ doc.get_formatted("posting_date") }}</td>
        </tr>
        {% if doc.due_date %}
        <tr>
          <td>Due Date</td>
          <td>{{ doc.get_formatted("due_date") }}</td>
        </tr>
        {% endif %}
      </table>
    </div>
  </div>

  <!-- ITEMS TABLE -->
  <table class="items-table">
    <colgroup>
      <col style="width:28px">
      <col>
      <col style="width:65px">
      <col style="width:105px">
      <col style="width:105px">
    </colgroup>
    <thead>
      <tr>
        <th>#</th>
        <th>Item / Description</th>
        <th class="r">Qty</th>
        <th class="r">Unit Rate</th>
        <th class="r">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="item-sr">{{ "%02d"|format(row.idx) }}</td>
        <td>
          <div class="item-code">{{ row.item_name }}</div>
          {% if row.description %}
          <div class="item-desc">{{ row.description | safe }}</div>
          {% endif %}
        </td>
        <td class="r">
          {{ row.qty }}
          <span class="item-uom">{{ row.uom }}</span>
        </td>
        <td class="r">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
        <td class="r">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- SUMMARY -->
  <div class="summary-wrap">
    <table class="summary-table">
      <tr>
        <td>Subtotal</td>
        <td>{{ frappe.utils.fmt_money(doc.total, currency=doc.currency) }}</td>
      </tr>
      {% for tax in doc.taxes %}
        {% if tax.tax_amount %}
        <tr class="summary-divider">
          <td>{{ tax.description }}</td>
          <td>{{ frappe.utils.fmt_money(tax.tax_amount, currency=doc.currency) }}</td>
        </tr>
        {% endif %}
      {% endfor %}
      {% if doc.discount_amount %}
      <tr class="summary-discount">
        <td>Discount</td>
        <td>− {{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td>
      </tr>
      {% endif %}
      <tr class="summary-grand">
        <td>Grand Total</td>
        <td>{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
      </tr>
    </table>
  </div>

  <!-- TERMS -->
  {% if doc.terms %}
  <div class="terms-section">
    <div class="terms-label">Terms &amp; Conditions</div>
    <div class="terms-body">{{ doc.terms }}</div>
  </div>
  {% endif %}

  <!-- SIGNATURES -->
  <div class="sig-section">
    <div class="sig-block">
      <div class="sig-line">Customer Signature</div>
    </div>
    <div class="sig-block">
      <div class="sig-line sig-right">Authorized Signatory</div>
    </div>
  </div>

  <!-- FOOTER -->
  <div class="doc-footer">{{ _company_website or _company_name }}</div>
